@DisplayName("110/108_convert_sorted_array_to_binary_search_tree (incomplete)")
class SolutionIncompleteTest {

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldBuildBalancedTreeFromFiveElements() {

        Solution solution = new Solution();

        TreeNode root = solution.sortedArrayToBST(new int[]{-10, -3, 0, 5, 9});

        assertEquals(0, root.val);
        assertTrue(isValidBst(root, Long.MIN_VALUE, Long.MAX_VALUE));
        assertTrue(isHeightBalanced(root));
        assertEquals(5, countNodes(root));
    }

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldBuildBalancedTreeFromTwoElements() {

        Solution solution = new Solution();

        TreeNode root = solution.sortedArrayToBST(new int[]{1, 3});

        assertTrue(isValidBst(root, Long.MIN_VALUE, Long.MAX_VALUE));
        assertTrue(isHeightBalanced(root));
        assertEquals(2, countNodes(root));
    }

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldHandleSingleElement() {

        Solution solution = new Solution();

        TreeNode root = solution.sortedArrayToBST(new int[]{1});

        assertEquals(1, root.val);
        assertNull(root.left);
        assertNull(root.right);
    }

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldBuildBalancedTreeFromThreeElements() {

        Solution solution = new Solution();

        TreeNode root = solution.sortedArrayToBST(new int[]{1, 2, 3});

        assertEquals(2, root.val);
        assertEquals(1, root.left.val);
        assertEquals(3, root.right.val);
        assertTrue(isHeightBalanced(root));
    }

    private boolean isValidBst(TreeNode node, long min, long max) {

        if (node == null) {
            return true;
        }

        if (node.val <= min || node.val >= max) {
            return false;
        }

        return isValidBst(node.left, min, node.val)
            && isValidBst(node.right, node.val, max);
    }

    private boolean isHeightBalanced(TreeNode node) {

        return height(node) != -1;
    }

    private int height(TreeNode node) {

        if (node == null) {
            return 0;
        }

        int left = height(node.left);
        int right = height(node.right);

        if (left == -1 || right == -1 || Math.abs(left - right) > 1) {
            return -1;
        }

        return Math.max(left, right) + 1;
    }

    private int countNodes(TreeNode node) {

        if (node == null) {
            return 0;
        }

        return 1 + countNodes(node.left) + countNodes(node.right);
    }
}

